From 1bc5648a21417b198592a84cd0646be98ebe1b14 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 20:52:32 +0100
Subject: [PATCH] desktoppackage: add Defaults and Reset buttons to widget
 settings

Widget and desktop settings only had OK, Apply and Cancel, so there was
no way to undo edits or go back to defaults short of closing the dialog.
Add Defaults and Reset buttons like the ones in System Settings.

BUG: 482702
---
 .../configuration/AppletConfiguration.qml     | 87 ++++++++++++++++++-
 .../ConfigurationContainmentActions.qml       |  3 +
 .../ConfigurationContainmentAppearance.qml    | 14 ++-
 3 files changed, 99 insertions(+), 5 deletions(-)

diff --git a/desktoppackage/contents/configuration/AppletConfiguration.qml b/desktoppackage/contents/configuration/AppletConfiguration.qml
index e452c7917e..2b38e2a0ff 100644
--- a/desktoppackage/contents/configuration/AppletConfiguration.qml
+++ b/desktoppackage/contents/configuration/AppletConfiguration.qml
@@ -39,6 +39,14 @@ Rectangle {

     property bool wasConfigurationChangedSignalSent: false

+    property var currentCategory: null
+
+    property bool currentPageHasDefaults: false
+    property bool currentPageIsDefaults: true
+    // Default values as the page holds them after loading them, which can differ from the raw
+    // config defaults when the page normalizes its values
+    property var loadedDefaults: ({})
+
     function closing() {
         if (applyButton.enabled) {
             messageDialog.item = null;
@@ -103,6 +111,59 @@ Rectangle {

     function settingValueChanged() {
         applyButton.enabled = wasConfigurationChangedSignalSent || isConfigurationChanged() || (app?.pageStack?.currentItem?.unsavedChanges ?? false);
+        updateDefaultsState();
+    }
+
+    // Keys of the applet configuration that the current page edits and that have a default value
+    function defaultableKeys() {
+        const page = app.pageStack.currentItem;
+        if (!page) {
+            return [];
+        }
+        const keys = Plasmoid.configuration.keys();
+        return keys.filter(key => ("cfg_" + key) in page && keys.includes(key + "Default"));
+    }
+
+    function updateDefaultsState() {
+        const page = app.pageStack.currentItem;
+        if (page && typeof page.loadDefaults === "function") {
+            currentPageHasDefaults = true;
+            currentPageIsDefaults = false;
+            return;
+        }
+        const config = Plasmoid.configuration;
+        const keys = defaultableKeys();
+        currentPageHasDefaults = keys.length > 0;
+        currentPageIsDefaults = keys.every(key => {
+            const value = page["cfg_" + key];
+            const defaultValue = key in loadedDefaults ? loadedDefaults[key] : config[key + "Default"];
+            return value == defaultValue || String(value) == String(defaultValue);
+        });
+    }
+
+    function loadDefaults() {
+        let page = app.pageStack.currentItem;
+        if (typeof page.loadDefaults === "function") {
+            page.loadDefaults();
+            return;
+        }
+        // Reload the page with the default values, so pages that only read their cfg_ properties
+        // when created show them too
+        open(currentCategory, true);
+        page = app.pageStack.currentItem;
+        const values = {};
+        defaultableKeys().forEach(key => values[key] = page["cfg_" + key]);
+        loadedDefaults = values;
+        settingValueChanged();
+    }
+
+    function resetConfig() {
+        const page = app.pageStack.currentItem;
+        if (typeof page.resetConfig === "function") {
+            page.resetConfig();
+        }
+        wasConfigurationChangedSignalSent = false;
+        open(currentCategory);
     }

     function pushReplace(item, config) {
@@ -115,9 +176,13 @@ Rectangle {
         app.currentConfigPage = page;
     }

-    function open(item) {
+    function open(item, useDefaults = false) {
         app.isAboutPage = false;
+        if (item !== root.currentCategory) {
+            root.loadedDefaults = {};
+        }
         root.currentSource = item.source
+        root.currentCategory = item

         if (item.configUiModule && item.configUiComponent) {
             root.currentSource = item.configUiModule + item.configUiComponent; // Just for the highlight status
@@ -128,7 +193,7 @@ Rectangle {
             };

             config.keys().forEach(key => {
-                props["cfg_" + key] = config[key];
+                props["cfg_" + key] = useDefaults && config.keys().includes(key + "Default") ? config[key + "Default"] : config[key];
             });

             pushReplace(Qt.createComponent(item.configUiModule, item.configUiComponent), props);
@@ -140,7 +205,7 @@ Rectangle {
             const props = { "title": item.name };

             config.keys().forEach(key => {
-                props["cfg_" + key] = config[key];
+                props["cfg_" + key] = useDefaults && config.keys().includes(key + "Default") ? config[key + "Default"] : config[key];
             });

             pushReplace(Qt.resolvedUrl(item.source), props);
@@ -149,6 +214,7 @@ Rectangle {
         }

         applyButton.enabled = false
+        updateDefaultsState()
     }

     Connections {
@@ -428,6 +494,21 @@ Rectangle {
                 id: buttonsRow
                 spacing: Kirigami.Units.smallSpacing

+                QQC2.Button {
+                    icon.name: "document-revert"
+                    text: i18ndc("plasma_shell_org.kde.plasma.desktop", "@action:button", "Defaults")
+                    visible: !app.isAboutPage && root.currentPageHasDefaults
+                    enabled: !root.currentPageIsDefaults
+                    onClicked: root.loadDefaults()
+                }
+                QQC2.Button {
+                    icon.name: "edit-undo"
+                    text: i18ndc("plasma_shell_org.kde.plasma.desktop", "@action:button", "Reset")
+                    visible: !app.isAboutPage && (app.pageStack.currentItem?.resettable ?? true)
+                    enabled: applyButton.enabled
+                    onClicked: root.resetConfig()
+                }
+
                 Item {
                     Layout.fillWidth: true
                 }
diff --git a/desktoppackage/contents/configuration/ConfigurationContainmentActions.qml b/desktoppackage/contents/configuration/ConfigurationContainmentActions.qml
index 5cac407e79..395b51de4c 100644
--- a/desktoppackage/contents/configuration/ConfigurationContainmentActions.qml
+++ b/desktoppackage/contents/configuration/ConfigurationContainmentActions.qml
@@ -15,6 +15,9 @@ KCM.SimpleKCM {

     signal configurationChanged

+    // Changes are kept in configDialog.currentContainmentActionsModel, which can't reload them
+    readonly property bool resettable: false
+
     property var prettyStrings: {
         "LeftButton": i18ndc("plasma_shell_org.kde.plasma.desktop", "@label for shortcuts", "Left-Button"),
         "RightButton": i18ndc("plasma_shell_org.kde.plasma.desktop", "@label for shortcuts", "Right-Button"),
diff --git a/desktoppackage/contents/configuration/ConfigurationContainmentAppearance.qml b/desktoppackage/contents/configuration/ConfigurationContainmentAppearance.qml
index 9d4c36f4aa..d4d1a5dbe6 100644
--- a/desktoppackage/contents/configuration/ConfigurationContainmentAppearance.qml
+++ b/desktoppackage/contents/configuration/ConfigurationContainmentAppearance.qml
@@ -56,6 +56,15 @@ SimpleKCM {
         })
     }

+    function loadDefaults() {
+        main.loadSourceFile(true)
+        appearanceRoot.checkUnsavedChanges()
+    }
+
+    function resetConfig() {
+        configDialog.currentWallpaper = appearanceRoot.originalWallpaper
+    }
+
     ColumnLayout {
         width: appearanceRoot.availableWidth
         height: Math.max(implicitHeight, appearanceRoot.availableHeight)
@@ -141,7 +150,7 @@ SimpleKCM {

             onSourceFileChanged: loadSourceFile()

-            function loadSourceFile() {
+            function loadSourceFile(useDefaults = false) {
                 const wallpaperConfig = configDialog.wallpaperConfiguration
                 // BUG 407619: wallpaperConfig can be null before calling `ContainmentItem::loadWallpaper()`
                 if (wallpaperConfig && sourceFile) {
@@ -161,7 +170,8 @@ SimpleKCM {
                     wallpaperConfig.keys().forEach(key => {
                         const cfgKey = "cfg_" + key;
                         if (cfgKey in temp) {
-                            props[cfgKey] = wallpaperConfig[key]
+                            const defaultKey = key + "Default"
+                            props[cfgKey] = useDefaults && wallpaperConfig.keys().includes(defaultKey) ? wallpaperConfig[defaultKey] : wallpaperConfig[key]
                         }
                     })
                     temp.destroy()
-- 
2.53.0
